/* Cognitive Care NER — Adaptive game runtime v5.
 * Fixes the v4 round-state crash and keeps the five-game adaptive protocol.
 */
(() => {
  'use strict';
  if (window.CCNER_ADAPTIVE_GAME_ENGINE_V5) return;
  window.CCNER_ADAPTIVE_GAME_ENGINE_V5 = true;

  const $ = s => document.querySelector(s);
  const clamp = (n,a,b) => Math.max(a, Math.min(b,n));
  const shuffle = a => { const x=[...a]; for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1)); [x[i],x[j]]=[x[j],x[i]];} return x; };
  const pick = a => a[Math.floor(Math.random()*a.length)];
  const now = () => performance.now();
  const HISTORY='ccner-history';
  const AIKEY='ccner-ai-game-profile-v5';
  const ORDERKEY='ccner-last-game-order-v5';

  const COLORS=[
    {id:'red',label:'Red',hex:'#b83d4b'},
    {id:'blue',label:'Blue',hex:'#3f6db6'},
    {id:'green',label:'Green',hex:'#32925a'},
    {id:'yellow',label:'Yellow',hex:'#a78b19'}
  ];
  const HOUSE={
    desk:[['Stapler','🖇️'],['Can Opener','🥫'],['Envelopes','✉️'],['Measuring Spoons','🥄'],['Paperclips','📎'],['Oven Mitt','🧤']],
    kitchen:[['Can Opener','🥫'],['Measuring Spoons','🥄'],['Oven Mitt','🧤'],['Tea Strainer','🫖'],['Serving Spoon','🥄'],['Tea Cup','☕']],
    porch:[['Rocking Chair','🪑'],['Fire Poker','🔥'],['Welcome Mat','🧶'],['Firewood','🪵'],['Porch Swing','🛋️'],['Bellows','🪶']],
    fireplace:[['Fire Poker','🔥'],['Firewood','🪵'],['Bellows','🪶'],['Rocking Chair','🪑'],['Porch Swing','🛋️'],['Welcome Mat','🧶']],
    bathroom:[['Toothbrush','🪥'],['Bath Towel','🛁'],['Shower Cap','🧢'],['Soap','🧼'],['Comb','🪮'],['Toothpaste','🧴']],
    bedroom:[['Pillow','🛏️'],['Alarm Clock','⏰'],['Dresser','🗄️'],['Blanket','🧣'],['Bedside Lamp','💡'],['Book','📖']],
    china:[['Teacups','☕'],['Serving Platter','🍽️'],['Gravy Boat','🫕'],['Tea Pot','🫖'],['Saucer','🍵'],['Bowl','🥣']],
    broom:[['Broom','🧹'],['Dustpan','🗑️'],['Mop','🪣'],['Cleaning Cloth','🧽'],['Brush','🧹'],['Bucket','🪣']]
  };
  const HOUSE_ROOMS=[['Writing Desk','Kitchen Drawer','desk','kitchen'],['Front Porch','Fireplace','porch','fireplace'],['Bathroom','Bedroom','bathroom','bedroom'],['China Cabinet','Broom Closet','china','broom']];
  const VISUALS=['🍎','🥭','🍌','🍊','☕','💧','🥄','📖','🍚','🥥','🧺','🪣','🌂','🧴','💊','🌸'];
  const PATTERNS=[
    {seq:[1,2,3,4,5],answer:6,opts:[5,6,7,8],note:'Add 1 each time.'},
    {seq:[2,4,6,8,10],answer:12,opts:[11,12,14,16],note:'Add 2 each time.'},
    {seq:[3,6,9,12,15],answer:18,opts:[16,18,20,21],note:'Add 3 each time.'},
    {seq:[2,4,8,16,32],answer:64,opts:[48,60,64,72],note:'Double each time.'},
    {seq:[5,10,15,20,25],answer:30,opts:[28,30,35,40],note:'Add 5 each time.'},
    {seq:[1,4,9,16,25],answer:36,opts:[30,32,36,49],note:'These are square numbers.'},
    {seq:[2,5,10,17,26],answer:37,opts:[34,36,37,39],note:'Add consecutive odd numbers.'},
    {seq:[10,20,40,80,160],answer:320,opts:[240,280,320,360],note:'Double each time.'}
  ];
  const SPOT_BASE=[['⭐','🌙','☀️','🌈','⚡','🍀','❤️','🔔'],['🎸','🎹','🥁','🎺','🎻','🪗','🎷','🪕'],['🍰','🧁','🍩','🍪','🎂','🍫','🍬','🍭'],['🍎','🍌','🍇','🍊','🍉','🥭','🍐','🍓'],['☕','🥄','🍚','🥣','🫖','🍵','🍞','🧂']];
  const GAMES={
    sequence:{title:'Sequence Memory',category:'MEMORY + ATTENTION',count:6,kind:'rounds',intro:'Watch the colours light up, then repeat the sequence from memory.',training:'Short-term memory and attention'},
    stroop:{title:'Stroop Test',category:'ATTENTION + CONCENTRATION',count:120,kind:'timed',seconds:120,intro:'Choose the ink colour, not the word.',training:'Selective attention and response control'},
    house:{title:'Around the House Sorting',category:'DAILY-LIFE RECOGNITION',count:10,kind:'rounds',intro:'Tap each item, then choose the category where it belongs.',training:'Daily-life recognition and categorisation'},
    pattern:{title:'Pattern Recognition',category:'PATTERN RECOGNITION',count:15,kind:'rounds',intro:'Find the pattern and choose what comes next.',training:'Pattern recognition and reasoning'},
    spot:{title:'Spot the Difference',category:'VISUAL ATTENTION',count:15,kind:'rounds',intro:'Look carefully at the items, then spot what changed.',training:'Visual attention and detail recognition'}
  };
  const KEYS=Object.keys(GAMES);
  const state={active:false,index:0,order:[],gameKey:null,round:1,results:[],trialStarted:0,gameStarted:0,locked:false,timer:null,sequence:null,house:null,spot:null};

  function read(k,f){try{return JSON.parse(localStorage.getItem(k)||'null')??f}catch(_){return f}}
  function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(_){}
  }
  const ai=read(AIKEY,{});
  KEYS.forEach(k=>{if(!ai[k])ai[k]={difficulty:2,attempts:0,correct:0,streak:0,avgResponse:0,lastAccuracy:0,lastUpdated:null};});
  function saveAI(){write(AIKEY,ai)}
  function difficulty(k){return clamp(Number(ai[k]?.difficulty||2),1,10)}
  function speedTarget(k,d){if(k==='stroop')return clamp(2.9-(d-1)*.16,1.45,2.9);if(k==='sequence')return clamp(5.4-(d-1)*.25,3,5.4);if(k==='house')return clamp(4.6-(d-1)*.18,2.9,4.6);if(k==='pattern')return clamp(6-(d-1)*.22,3.6,6);return clamp(5.5-(d-1)*.18,3,5.5)}
  function adapt(k,correct,ms){const p=ai[k],sec=ms/1000,target=speedTarget(k,p.difficulty),fast=sec<=target;p.attempts++;if(correct){p.correct++;p.streak=(p.streak||0)+1}else p.streak=0;p.lastAccuracy=p.correct/p.attempts;p.avgResponse=p.avgResponse?(.82*p.avgResponse+.18*sec):sec;if(correct&&fast&&p.streak>=2)p.difficulty=clamp(p.difficulty+1,1,10);else if(!correct&&p.attempts%2===0)p.difficulty=clamp(p.difficulty-1,1,10);else if(!correct&&sec>target*1.8)p.difficulty=clamp(p.difficulty-1,1,10);p.lastUpdated=new Date().toISOString();saveAI()}
  function setText(sel,text){const e=$(sel);if(e)e.textContent=text}
  function injectCSS(){
    if($('#ccner-v5-style'))return;
    const s=document.createElement('style');s.id='ccner-v5-style';s.textContent=`
      body.ccner-adaptive-v5{background:radial-gradient(circle at 50% -12%,rgba(72,160,113,.16),transparent 36%),#07120d!important;color:#edf3ee!important}
      body.ccner-adaptive-v5 .topbar,body.ccner-adaptive-v5 footer,body.ccner-adaptive-v5 .home-strip,body.ccner-adaptive-v5 .info-grid,body.ccner-adaptive-v5 .section-label{display:none!important}
      body.ccner-adaptive-v5 .app-shell{width:min(900px,calc(100% - 28px));padding:14px 0 82px}
      body.ccner-adaptive-v5 .game-top{max-width:650px;margin:18px auto 12px}.v5-meta{max-width:650px;margin:5px auto 10px;display:flex;justify-content:space-between;gap:10px;color:#a8baae;font-size:.82rem}.v5-ai{color:#59ca8c;font-weight:900}.v5-rounds{display:flex;gap:5px;justify-content:center;margin:10px}.v5-rounds i{width:9px;height:9px;border-radius:50%;background:#34433a}.v5-rounds i.on{background:#53c58a}.v5-status{text-align:center;color:#c7d6cd;font-weight:800;margin:12px 0}.v5-colors{display:grid;grid-template-columns:repeat(2,110px);gap:14px;justify-content:center;margin:18px auto}.v5-color{width:110px;height:92px;border:2px solid rgba(255,255,255,.12);border-radius:18px;cursor:pointer}.v5-color.red{background:#a72f40}.v5-color.blue{background:#315a9f}.v5-color.green{background:#278d50}.v5-color.yellow{background:#9d8012}.v5-color.flash{filter:brightness(1.55);box-shadow:0 0 0 5px rgba(255,255,255,.1),0 0 28px rgba(255,255,255,.2)}.v5-choice-grid{display:grid;grid-template-columns:repeat(2,minmax(130px,1fr));gap:10px;max-width:560px;margin:15px auto}.v5-choice{min-height:58px;border:1px solid #2d4a3a;border-radius:11px;background:#0b1811;color:#dce9e1;font-weight:850;font-size:1rem;cursor:pointer;padding:10px}.v5-timer{text-align:center;font-size:1.25rem;font-weight:950;color:#61cb92;margin:10px}.v5-stroop{font-size:clamp(3.1rem,8vw,5rem);font-weight:950;text-align:center;margin:24px 0 18px}.v5-house-list{display:grid;gap:9px}.v5-house-row{display:grid;grid-template-columns:minmax(130px,1fr) minmax(220px,1fr);gap:8px;align-items:center;padding:8px 10px;background:#09150f;border:1px solid #263e31;border-radius:11px}.v5-house-buttons{display:grid;grid-template-columns:1fr 1fr;gap:6px}.v5-house-btn,.v5-check,.v5-next{min-height:46px;border:0;border-radius:10px;background:#07110c;color:#bdcfc4;font-weight:850;padding:7px;cursor:pointer}.v5-house-btn.selected,.v5-check,.v5-next{background:#2c8659;color:#e7fff0}.v5-check{width:100%;margin-top:10px}.v5-check:disabled{opacity:.45}.v5-house-row.correct{border-color:#4bc287;background:#102b1f}.v5-house-row.wrong{border-color:#bd5d54;background:#2a1615}.v5-pattern{display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;margin:22px 0}.v5-pcell{min-width:52px;min-height:52px;display:grid;place-items:center;padding:7px 10px;border-radius:11px;background:#0b2116;color:#55c98b;font-weight:900;font-size:1.25rem;border:1px solid #1d4530}.v5-pcell.q{border:1px dashed #55c98b}.v5-spot-memory,.v5-spot-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0}.v5-spot-memory span,.v5-spot{min-height:70px;display:grid;place-items:center;border-radius:12px;background:#0a1c12;border:1px solid #294b38;font-size:2rem}.v5-spot{cursor:pointer}.v5-spot:hover{border-color:#50c487}.v5-finish{text-align:center;padding:28px 12px}.v5-finish strong{font-size:2rem;color:#5ed092}.v5-next{margin-top:14px;padding:0 22px}.v5-explain{margin:12px auto;padding:10px;border-radius:10px;background:#0a1a11;color:#b9cbbf;text-align:center}@media(max-width:600px){.v5-house-row{grid-template-columns:1fr}.v5-spot-memory,.v5-spot-grid{grid-template-columns:repeat(4,1fr);gap:7px}.v5-spot{font-size:1.65rem}.v5-colors{grid-template-columns:repeat(2,100px)}.v5-color{width:100px;height:84px}}
    `;document.head.appendChild(s)
  }
  function chrome(k){const g=GAMES[k];document.body.classList.add('ccner-adaptive-v5');setText('#gameCategory',g.category);setText('#gameTitle',g.title);setText('#gamePrompt',g.intro);setText('#gameMomoText',`Adaptive practice · Difficulty ${difficulty(k)}/10`);let m=$('#v5meta');if(!m){const a=$('#gameArea');if(a){a.insertAdjacentHTML('beforebegin',`<div id="v5meta" class="v5-meta"><span class="v5-ai">AI-adaptive training</span><span id="v5difficulty"></span><span id="v5count"></span></div>`);m=$('#v5meta')}}}
  function meta(){const k=state.gameKey,g=GAMES[k];setText('#v5difficulty',`Difficulty ${difficulty(k)}/10`);setText('#v5count',g.kind==='timed'?`${Math.max(0,Math.ceil(g.seconds-(now()-state.gameStarted)/1000))}s remaining`:`Test ${state.round} / ${g.count}`)}
  function clearTimers(){if(state.timer){cancelAnimationFrame(state.timer);clearTimeout(state.timer);state.timer=null}}
  function record(correct,extra={}){const ms=now()-state.trialStarted;adapt(state.gameKey,correct,ms);state.results.push({game:state.gameKey,trial:state.round,correct,responseMs:ms,seconds:ms/1000,difficulty:difficulty(state.gameKey),...extra});}
  function advance(correct,extra={}){if(state.locked)return;state.locked=true;record(correct,extra);setText('#gameFeedback',correct?'Correct!':'Good try. Let’s keep practicing.');setTimeout(()=>{state.locked=false;if(!state.active)return;if(state.gameKey==='stroop'){if(now()-state.gameStarted>=120000){finishGame();return}beginRound();return}if(state.round>=GAMES[state.gameKey].count){finishGame();return}state.round++;beginRound()},520)}
  function beginRound(){if(!state.active)return;state.trialStarted=now();state.locked=false;meta();switch(state.gameKey){case'sequence':sequence();break;case'stroop':stroop();break;case'house':house();break;case'pattern':pattern();break;case'spot':spot();break}}
  function sequence(){const d=difficulty('sequence'),len=clamp(3+Math.floor((d-1)/2)+Math.floor((state.round-1)/2),3,10),gap=clamp(720-d*28,440,720),seq=Array.from({length:len},()=>pick(COLORS));state.sequence={seq,pos:0};const a=$('#gameArea');a.innerHTML=`<div class="v5-rounds">${Array.from({length:6},(_,i)=>`<i class="${i<state.round?'on':''}"></i>`).join('')}</div><div class="v5-status" id="v5seqstatus">Watch carefully…</div><div class="v5-colors">${COLORS.map(c=>`<button class="v5-color ${c.id}" data-color="${c.id}" aria-label="${c.label}"></button>`).join('')}</div>`;const tiles=[...a.querySelectorAll('.v5-color')];let i=0;const flash=()=>{if(!state.active)return;tiles.forEach(x=>x.classList.remove('flash'));if(i<seq.length){tiles.find(x=>x.dataset.color===seq[i].id)?.classList.add('flash');i++;setTimeout(flash,gap);return}setText('#v5seqstatus','Your turn — repeat the sequence.');tiles.forEach(t=>t.onclick=()=>{if(state.locked)return;const ok=t.dataset.color===seq[state.sequence.pos]?.id;if(!ok){advance(false,{expected:seq[state.sequence.pos]?.id,chosen:t.dataset.color});return}t.classList.add('flash');state.sequence.pos++;if(state.sequence.pos===seq.length)advance(true,{sequenceLength:seq.length});setTimeout(()=>t.classList.remove('flash'),180)})};setTimeout(flash,420)}
  function stroop(){const d=difficulty('stroop'),visible=COLORS.slice(0,clamp(2+Math.floor(d/3),2,4)),word=pick(visible),ink=pick(visible),a=$('#gameArea');a.innerHTML=`<div class="v5-timer" id="v5timer"></div><div class="v5-status">Choose the ink colour, not the word.</div><div class="v5-stroop" style="color:${ink.hex}">${word.label.toUpperCase()}</div><div class="v5-choice-grid">${visible.map(c=>`<button class="v5-choice" data-id="${c.id}">${c.label}</button>`).join('')}</div>`;const tick=()=>{if(!state.active)return;const remain=Math.max(0,120-Math.floor((now()-state.gameStarted)/1000));setText('#v5timer',`Time remaining: ${remain}s`);if(remain>0)state.timer=requestAnimationFrame(tick);else finishGame()};state.timer=requestAnimationFrame(tick);a.querySelectorAll('.v5-choice').forEach(b=>b.onclick=()=>advance(b.dataset.id===ink.id,{ink:ink.id,word:word.id}))}
  function house(){const d=difficulty('house'),pair=HOUSE_ROOMS[(state.round-1)%HOUSE_ROOMS.length],size=clamp(4+Math.floor((d-1)/3),4,6),source=HOUSE[pair[2]],other=HOUSE[pair[3]],items=shuffle([...source.slice(0,Math.ceil(size/2)),...other.slice(0,Math.floor(size/2))]);state.house={pair,items,answers:{}};const a=$('#gameArea');a.innerHTML=`<div class="v5-status">Tap each item, then tap the category it belongs to.</div><div class="v5-house-list">${items.map((x,i)=>`<div class="v5-house-row" data-i="${i}"><div><span style="font-size:1.35rem;margin-right:7px">${x[1]}</span>${x[0]}</div><div class="v5-house-buttons"><button class="v5-house-btn" data-group="${pair[2]}">${pair[0]}</button><button class="v5-house-btn" data-group="${pair[3]}">${pair[1]}</button></div></div>`).join('')}</div><button class="v5-check" id="v5check" disabled>Check Answers</button>`;a.querySelectorAll('.v5-house-row').forEach(row=>row.querySelectorAll('.v5-house-btn').forEach(btn=>btn.onclick=()=>{row.querySelectorAll('.v5-house-btn').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');state.house.answers[row.dataset.i]=btn.dataset.group;$('#v5check').disabled=Object.keys(state.house.answers).length!==items.length}));$('#v5check').onclick=()=>{let ok=0;items.forEach((x,i)=>{const expected=source.includes(x)?pair[2]:pair[3],row=a.querySelector(`[data-i="${i}"]`);if(state.house.answers[i]===expected){ok++;row.classList.add('correct')}else row.classList.add('wrong')});advance(ok===items.length,{items:items.length,correctItems:ok})}}
  function pattern(){const d=difficulty('pattern');let p=pick(PATTERNS.slice(0,clamp(3+Math.floor(d/2),3,PATTERNS.length)));const shown=p.seq.slice(Math.max(0,p.seq.length-(4+Math.floor(d/4)))),a=$('#gameArea');a.innerHTML=`<div class="v5-pattern">${shown.map(x=>`<span class="v5-pcell">${x}</span>`).join('')}<span class="v5-pcell q">?</span></div><div class="v5-choice-grid">${shuffle(p.opts).map(x=>`<button class="v5-choice" data-answer="${x}">${x}</button>`).join('')}</div><div class="v5-explain" id="v5explain" hidden></div>`;a.querySelectorAll('.v5-choice').forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.answer)===p.answer;setText('#v5explain',ok?`Correct — ${p.note}`:`The rule was: ${p.note}`);$('#v5explain').hidden=false;advance(ok,{answer:p.answer,chosen:Number(b.dataset.answer),rule:p.note})})}
  function spot(){const d=difficulty('spot'),base=pick(SPOT_BASE),n=clamp(4+Math.floor(d/2),4,8),items=shuffle(base).slice(0,n),changedIndex=Math.floor(Math.random()*items.length),changed=pick(VISUALS.filter(x=>!items.includes(x))),altered=[...items];altered[changedIndex]=changed;state.spot={items,altered,changedIndex};const sec=clamp(5.5-(d-1)*.25,3,5.5),a=$('#gameArea');a.innerHTML=`<div class="v5-status" id="v5spotstatus">Memorize these items (${sec.toFixed(1)}s)</div><div class="v5-spot-memory">${items.map(x=>`<span>${x}</span>`).join('')}</div>`;setTimeout(()=>{if(!state.active)return;showSpot()},sec*1000)}
  function showSpot(){const a=$('#gameArea'),s=state.spot;if(!s)return;setText('#v5spotstatus','Which item changed?');a.querySelector('.v5-spot-memory')?.remove();const grid=document.createElement('div');grid.className='v5-spot-grid';grid.innerHTML=s.altered.map((x,i)=>`<button class="v5-spot" data-i="${i}">${x}</button>`).join('');a.appendChild(grid);grid.querySelectorAll('.v5-spot').forEach(b=>b.onclick=()=>advance(Number(b.dataset.i)===s.changedIndex,{changedIndex:s.changedIndex,chosen:Number(b.dataset.i)}))}
  function finishGame(){clearTimers();const g=GAMES[state.gameKey],rs=state.results.filter(r=>r.game===state.gameKey),correct=rs.filter(r=>r.correct).length,acc=rs.length?correct/rs.length:0,avg=rs.length?rs.reduce((n,r)=>n+r.seconds,0)/rs.length:0;const a=$('#gameArea');a.innerHTML=`<div class="v5-finish"><strong>${Math.round(acc*100)}% correct</strong><p>${g.kind==='timed'?`You trained for two minutes and completed ${rs.length} responses.`:`You completed ${rs.length} tests in this game.`}</p><p>Adaptive difficulty reached <b>${difficulty(state.gameKey)}/10</b>.</p><button class="v5-next" id="v5next">${state.index<state.order.length-1?'Next game':'Finish session'}</button></div>`;setText('#gameFeedback','');$('#v5next').onclick=()=>{if(state.index<state.order.length-1){state.index++;startGame(state.order[state.index])}else finishSession()};state.lastGame={key:state.gameKey,accuracy:acc,avgResponse:avg,difficulty:difficulty(state.gameKey),count:rs.length}}
  function startGame(k){clearTimers();state.gameKey=k;state.round=1;state.gameStarted=now();state.spot=null;state.house=null;state.sequence=null;chrome(k);setText('#gameCounter',`${state.index+1} of ${state.order.length}${k==='stroop'?' · 2:00':''}`);setText('#gameFeedback','');beginRound()}
  function newOrder(){const last=read(ORDERKEY,[]);let o=shuffle(KEYS);for(let i=0;i<20&&last.length===o.length&&o.every((x,j)=>x===last[j]);i++)o=shuffle(KEYS);write(ORDERKEY,o);return o}
  function startSession(){if(state.active)return;injectCSS();state.active=true;state.index=0;state.results=[];state.order=newOrder();const h=$('#homeView'),g=$('#gameView'),r=$('#resultsView');if(h)h.hidden=true;if(r)r.hidden=true;if(g)g.hidden=false;setText('#todayStatus','In progress');setTimeout(()=>startGame(state.order[0]),120)}
  function finishSession(){clearTimers();state.active=false;document.body.classList.remove('ccner-adaptive-v5');const rs=state.results,correct=rs.filter(r=>r.correct).length,acc=rs.length?correct/rs.length:0,avg=rs.length?rs.reduce((n,r)=>n+r.seconds,0)/rs.length:0;const h=read(HISTORY,[]);h.push({id:'v5-'+Date.now(),date:new Date().toISOString(),order:state.order,results:rs,accuracy:acc,avgResponse:avg,score:acc});write(HISTORY,h.slice(-50));const rv=$('#resultsView'),gv=$('#gameView');if(gv)gv.hidden=true;if(rv)rv.hidden=false;setText('#overallScore',Math.round(acc*100)+'%');setText('#overallAccuracy',Math.round(acc*100)+'%');setText('#gamesCompleted',`${new Set(rs.map(r=>r.game)).size} / 5`);setText('#avgTime',avg.toFixed(1)+'s');window.dispatchEvent(new CustomEvent('ccner:game-session-complete',{detail:{order:state.order,results:rs,accuracy:acc,avgResponse:avg}}))}
  function install(){injectCSS();window.CCNER_VIDEO_GAMES=window.CCNER_VIDEO_GAMES||{};window.CCNER_VIDEO_GAMES.startSession=startSession;window.CCNER_VIDEO_GAMES.startGame=startGame;}
  install();
})();
